function run_gate3e_r2_kao_vs_naive()    projectRoot = pwd();    addpath(fullfile(projectRoot, 'config'));    addpath(fullfile(projectRoot, 'src', 'published_generator'));    addpath(fullfile(projectRoot, 'src', 'stage_2a'));    addpath(fullfile(projectRoot, 'src', 'stage_2b_kao'));    cfg1 = stage_1_gate1_config(projectRoot);    cfg = stage_2b_kao_config(projectRoot);    outRoot = fullfile(projectRoot, 'results', 'paper_phenotypes', 'kao_vs_naive', 'dimensionality_alignment');    if ~exist(outRoot, 'dir'), mkdir(outRoot); end    nNetworks = 10;    nTargets = 8;    eventsKao = zeros(nNetworks, nTargets, 1); % MO only    eventsNaive = zeros(nNetworks, nTargets, 1);    PR_Kao = zeros(nNetworks, 2);    PR_Naive = zeros(nNetworks, 2);    Align_Obs = zeros(nNetworks, 2);    Align_Exp = zeros(nNetworks, 2);    pad_rates = @(rates, indices) ...        arrayfun(@(idx) rates(min(max(idx, 1), size(rates, 1)), :, :), indices, 'UniformOutput', false);    extract_window = @(rates, indices) cell2mat(pad_rates(rates, indices)');    for net = 1:nNetworks        fprintf('Network %d...\n', net);        d1 = load(fullfile(cfg.ensemble.stage1Root, sprintf('network_%02d.mat', net)), 'model');        model = d1.model;        d2a = load(fullfile(cfg.ensemble.stage2aRoot, sprintf('network_%02d_stage2a.mat', net)), 'networkResult');        tonicInput = d2a.networkResult.tonicInput;        d2b = load(fullfile(cfg.resultsRoot, 'ensemble', sprintf('network_%02d_stage2b_kao_controller.mat', net)), 'controllerSaved');        kaoController = d2b.controllerSaved;        durS = 0.500;        prepKao = simulate_stage2b_kao_preparation(model, kaoController, durS);        prepNaive = simulate_naive_preparation(model, tonicInput, durS);        ratesPrepKao = max(prepKao.states, 0);        ratesPrepNaive = max(prepNaive.states, 0);        goKao = squeeze(prepKao.states(end, :, :));        goNaive = squeeze(prepNaive.states(end, :, :));        moveKao = simulate_published_cortex(model, goKao, true);        moveNaive = simulate_published_cortex(model, goNaive, true);        ratesMoveKao = moveKao.rates;        ratesMoveNaive = moveNaive.rates;        [~, handKao] = simulate_published_arm(model, moveKao.torque);        [~, handNaive] = simulate_published_arm(model, moveNaive.torque);        for t = 1:8            % Kao events            vKao = vecnorm(handKao(:, [2, 4], t), 2, 2);            [vpK, pkIdxK] = max(vKao);            moThreshK = 0.20 * vpK;            moIdxK = find(vKao >= moThreshK, 1, 'first');            if isempty(moIdxK), error('No valid event Kao %d', t); end            eventsKao(net, t, 1) = moIdxK - 1;            % Naive events            vN = vecnorm(handNaive(:, [2, 4], t), 2, 2);            [vpN, pkIdxN] = max(vN);            moThreshN = 0.20 * vpN;            moIdxN = find(vN >= moThreshN, 1, 'first');            if isempty(moIdxN), error('No valid event Naive %d', t); end            eventsNaive(net, t, 1) = moIdxN - 1;        end        % Normalize        idxPrepRef = 101:10:501;        refPrep = ratesPrepKao(idxPrepRef, :, :);        refMove = zeros(41, 200, 8);        for t = 1:8            mo = eventsKao(net, t, 1);            idxMoveRef = (mo - 50 + 1) : 10 : (mo + 350 + 1);            refMove(:, :, t) = extract_window(ratesMoveKao(:, :, t), idxMoveRef);        end        refConcat = cat(1, refPrep, refMove);        refFlat = reshape(refConcat, [], 200);        normSD = max(std(refFlat, 0, 1), 1);        refConcatNorm = refConcat ./ reshape(normSD, 1, 200, 1);        refMean = mean(refConcatNorm, 3);        refCentered = refConcatNorm - repmat(refMean, 1, 1, 8);        Ymat = reshape(refCentered, [], 200);        CYfull = Ymat' * Ymat;        for ep = 1:2            rKao = zeros(11, 200, 8);            rNaive = zeros(11, 200, 8);            if ep == 1                idx = 401:10:501;                rKao = ratesPrepKao(idx, :, :);                rNaive = ratesPrepNaive(idx, :, :);            elseif ep == 2                for t = 1:8                    moK = eventsKao(net, t, 1);                    idxK = (moK + 1) : 10 : (moK + 100 + 1);                    rKao(:, :, t) = extract_window(ratesMoveKao(:, :, t), idxK);                    moN = eventsNaive(net, t, 1);                    idxN = (moN + 1) : 10 : (moN + 100 + 1);                    rNaive(:, :, t) = extract_window(ratesMoveNaive(:, :, t), idxN);                end            end            rKao = rKao ./ reshape(normSD, 1, 200, 1);            rNaive = rNaive ./ reshape(normSD, 1, 200, 1);            cKao = rKao - repmat(mean(rKao, 3), 1, 1, 8);            cNaive = rNaive - repmat(mean(rNaive, 3), 1, 1, 8);            X_Kao = reshape(cKao, [], 200);            X_Naive = reshape(cNaive, [], 200);            C_Kao = X_Kao' * X_Kao;            C_Naive = X_Naive' * X_Naive;            [~, lamKao] = get_eig(C_Kao);            [W_Naive, lamNaive] = get_eig(C_Naive);            PR_Kao(net, ep) = sum(lamKao)^2 / max(sum(lamKao.^2), eps);            PR_Naive(net, ep) = sum(lamNaive)^2 / max(sum(lamNaive.^2), eps);            denom = sum(lamKao(1:15));            AI_obs = trace(W_Naive(:, 1:15)' * C_Kao * W_Naive(:, 1:15)) / max(denom, eps) * 100;            Align_Obs(net, ep) = AI_obs;            seed = 66000 + net * 10 + ep;            Align_Exp(net, ep) = compute_null_alignment(C_Kao, CYfull, denom, seed);        end    end    save(fullfile(outRoot, 'gate3e_r2_data.mat'), 'eventsKao', 'eventsNaive', ...        'PR_Kao', 'PR_Naive', 'Align_Obs', 'Align_Exp');    disp('Data saved.');endfunction medianNull = compute_null_alignment(CX, CYfull, denom, seed)    [U, D] = get_eig(CYfull);    biasMtx = U * diag(sqrt(max(D, 0)));    nullAIs = zeros(10000, 1);    rng(seed, 'twister');    for i = 1:10000        r = randn(200, 15);        [Q1, ~] = qr(r, 0);        r2 = biasMtx * Q1;        [Q2, ~] = qr(r2, 0);        nullAIs(i) = trace(Q2' * CX * Q2) / max(denom, eps) * 100;    end    medianNull = median(nullAIs);endfunction [V, D] = get_eig(C)    C = (C + C') / 2;    [V, D_mat] = eig(C, 'vector');    [D, ord] = sort(D_mat, 'descend');    V = V(:, ord);end
